begin;

delete from public.sections where page_id = (select id from public.pages where slug = '/launch-sprints');
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Launch Sprints","heading":"A Fixed Scope, With a Finish Date","body":"A Launch Sprint is a single engagement with a defined start, a defined end, and a written list of everything included. There is no term, no renewal, and no obligation to continue afterwards.","primaryCta":{"label":"Request a Sprint Consultation","href":"/contact?type=sprint"},"showcase":[{"kind":"growth","label":"Fixed window","title":"The Sprint","items":["Audit","Implementation","Handoff","30-Day Action Roadmap"]}]}'::jsonb, 0 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-a-sprint-is', 'featureSplit', 'surface', '{"eyebrow":"The Shape of It","heading":"What a Sprint Is","body":"A Launch Sprint is a single piece of SEO work with a start date, an end date, and a list agreed before anything begins. It is not a trial of monthly service, and it is not a discounted version of it.\n\nIt is the foundational work — the audit, the technical and on-page fixes, the setup that should be in place before any ongoing campaign — done once, as its own job, with its own price.\n\nMost SEO engagements spend their first two months doing exactly this work inside a retainer while the invoice runs. A sprint separates it out and puts a finish date on it, so a business can buy the foundation without committing to a year of anything.\n\nAt the end you get the work itself and a written roadmap of what to do next. Whether that turns into monthly service, a job for an internal team, or nothing for a while is a real decision rather than a formality — the roadmap is written to be useful in all three cases.","groups":[{"title":"One-Time","icon":"rocket","body":"A single engagement. No term, no renewal, and no ongoing invoice arriving next month."},{"title":"A Defined Window","icon":"calendar","body":"A fixed start and a fixed end. The work is completed inside the window rather than running until somebody stops it."},{"title":"Fixed Scope","icon":"list-checks","body":"The deliverable list is the whole list, agreed before anything starts. What is on it gets done, and it is written down."}]}'::jsonb, 1 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'where-it-ends', 'cardGrid', 'white', '{"variant":"numbered","columns":3,"eyebrow":"The Boundary","heading":"Where a Sprint Ends","body":"Being precise about where a fixed-scope engagement stops is the same principle as reporting honestly. It just applies to scope instead.","cards":[{"title":"The List Is the Scope","body":"Everything included is written down before the work begins. Anything outside it is quoted separately rather than absorbed quietly or dropped without mention."},{"title":"The Window Closes","body":"30 days on a Neighborhood sprint, 45 on Regional and National. When it is up the work is delivered. There is no rollover into an open-ended timeline and no month four that nobody agreed to."},{"title":"A Foundation, Not a Campaign","body":"A sprint builds the base and hands over a roadmap. Ongoing growth is a separate decision, made afterwards with the roadmap in hand."}]}'::jsonb, 2 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprints', 'pricingCards', 'surface', '{"eyebrow":"The Three Sprints","heading":"Three Sprints, Sized by Reach","body":"Neighborhood is local work. Regional and National are technical and on-page work across markets. That is a difference in kind rather than in size, so none of the three is a step up from another.","packageIds":["sprint-neighborhood","sprint-regional","sprint-national"]}'::jsonb, 3 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'process', 'processSteps', 'white', '{"eyebrow":"Inside the Window","heading":"What Happens During the Sprint","steps":[{"title":"Audit","body":"The current foundation is reviewed end to end, the priority issues are identified and ranked, and the first fixes are confirmed with you before any of them happen."},{"title":"Implementation","body":"The included setup and optimization work is completed inside the agreed scope. Anything found along the way that sits outside it is flagged and quoted rather than absorbed."},{"title":"Handoff","body":"A clear roadmap with next-step recommendations in priority order, and a clean path into monthly service if that is what you decide to do."}]}'::jsonb, 4 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'roadmap', 'cardGrid', 'surface', '{"variant":"cards","columns":4,"emphasis":true,"eyebrow":"The Deliverable","heading":"What You Walk Away With","body":"The 30-Day Action Roadmap is the thing the sprint is actually for. Everything else is the work that makes it worth reading.","cards":[{"title":"Priority Findings","icon":"search","body":"What is holding visibility back, ranked by impact rather than listed in the order it was found."},{"title":"Completed Work","icon":"clipboard-check","body":"Everything done during the sprint, itemised, so there is no gap between what was paid for and what is visible."},{"title":"Recommended Next Steps","icon":"compass","body":"What to do next, in order, with the reasoning behind the order rather than just the list."},{"title":"A Clear Path Forward","icon":"target","body":"Whether that means monthly service or handling the roadmap internally. Both are real answers, and the roadmap is written to work either way."}]}'::jsonb, 5 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'waiver', 'waiverMatrix', 'white', '{"eyebrow":"Continuing On","heading":"Continuing Into Monthly Service","body":"The sprint deliverables and the onboarding work on a monthly package are close to the same job. That is why the waiver exists: a sprint is the onboarding done standalone, with a roadmap attached.","sprintHeading":"Sprint","waivesHeading":"Waives onboarding on","rows":[{"sprint":"Neighborhood","waives":"Neighborhood, Citywide, or Metro"},{"sprint":"Regional","waives":"Regional"},{"sprint":"National","waives":"National or National+"}],"condition":"Monthly service must begin within 30 calendar days of sprint completion.","cta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 6 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Sprint Questions","items":[{"question":"Is there any ongoing commitment?","answer":"None. A sprint is a one-time engagement with no term and no auto-renewal. When the window is up, the work is delivered and the arrangement is over unless you decide otherwise."},{"question":"How long does a sprint take?","answer":"A Neighborhood sprint runs 30 days. Regional and National run 45, because the audit and the on-page work cover more ground. At the end the 30-Day Action Roadmap is handed over along with everything completed during the sprint, and continuing into monthly service is optional."},{"question":"How does the onboarding waiver work?","answer":"If monthly service starts within 30 calendar days of the sprint finishing, the onboarding fee on the matching package is waived. The Neighborhood sprint covers Neighborhood, Citywide or Metro; Regional covers Regional; National covers National or National+."},{"question":"Which sprint fits?","answer":"Neighborhood is local work, including the Google Business Profile, citations and a local grid baseline. Regional and National are technical and on-page work across multiple markets. The difference is what a business competes in, not how large it is."},{"question":"Can the roadmap be handled internally?","answer":"Yes. It is written to be actionable by whoever ends up doing it, and plenty of businesses take it and run it themselves. That is a legitimate outcome rather than a failed one."},{"question":"Is a sprint required before monthly service?","answer":"No. It is one route in, not a gate. Monthly packages can start directly, with the standard onboarding fee."}],"cta":{"label":"Request a Sprint Consultation","href":"/contact?type=sprint"}}'::jsonb, 7 from public.pages where slug = '/launch-sprints';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Sprint","body":"A fixed scope, a fixed end date, and a roadmap at the end of it that is yours whatever you decide to do next.","primaryCta":{"label":"Request a Sprint Consultation","href":"/contact?type=sprint"},"secondaryCta":{"label":"View Monthly SEO Packages","href":"/monthly-seo-packages"}}'::jsonb, 8 from public.pages where slug = '/launch-sprints';
